node --input-type=module <<'EOF'
import { strict as assert } from 'node:assert';
import { refundCents } from './impl.ts';
const history = { merchantId: 'm1', captures: [] };
const refund = (capturedCents, requestedCents, settled, ageHours = 1) => refundCents({ id: 'c1', merchantId: 'm1', capturedCents, requestedCents, ageHours, settled }, history);
assert.equal(refund(1001, 900, false), 500);
assert.equal(refund(1001, 400, false), 400);
assert.equal(refund(1001, 900, true), 900);
assert.equal(refund(1001, 1200, true), 1001);
assert.equal(refund(1001, 900, true, 1), 900);
assert.equal(refund(1001, -10, true), 0);
assert.equal(refund(1001, Number.NaN, true), 0);
console.log('7 refund policy checks passed');
EOF
